-- Retire permissions for sections removed from the application on 2026-09-29.
-- Forward-only migration: historical migrations remain immutable.
create or replace function public._abu_bassam_permission_key_allowed(p_key text)
returns boolean
language sql
immutable
set search_path=public
as $$
  select coalesce(p_key,'') = any(array['edit','print','export','appearance','sync','security','devices','reset','deviceView','deviceAdd','deviceRename','deviceEnable','deviceDisable','deviceDelete','deviceLimit','devicePermissions','deviceRole','deviceForceLogout','deviceResetSecret','deviceViewLastSeen','deviceViewModel','deviceAudit','deviceBlockOffline','deviceSetOfflineHours','vaultView','vaultAdd','vaultEdit','vaultRename','vaultMove','vaultFolders','vaultFavorite','vaultDelete','vaultPermanentDelete','vaultRestoreDeleted','vaultPrint','vaultExport','vaultShare','vaultSaveGallery','vaultSavePdf','vaultOcr','vaultImageEdit','vaultCrop','vaultPerspective','vaultEnhance','vaultSync','vaultBackup','vaultRestoreBackup','vaultEncryptedBackup','vaultTransferBranch','vaultViewOtherBranches','vaultDeleteOtherBranch','privateVaultUse','privateVaultAdd','privateVaultView','privateVaultEdit','privateVaultDelete','privateVaultExport','privateVaultBackup','privateVaultRestore','privateVaultChangePassword','privateVaultReset','customerView','customerAdd','customerEdit','customerDelete','customerSearch','customerDocumentsView','customerDocumentsAdd','customerDocumentsEdit','customerDocumentsDelete','customerDocumentsPrint','customerDocumentsExport','customerTransferBranch','customerViewOtherBranches','customerPhoneView','customerSensitiveDataView','customerOriginalDocumentView','cardsView','cardsCreate','cardsEdit','cardsDelete','cardsDuplicate','cardsTemplatesEdit','cardsTemplatesDelete','cardsImportImage','cardsEditImage','cardsEditText','cardsQr','cardsBarcode','cardsPrint','cardsExportImage','cardsExportPdf','cardsA4Layout','cardsSaveTemplate','cardsManageCustomTemplates','printGeneral','printDocuments','printCards','printCustomerDocuments','printA4','printCardDirect','printerProfiles','printerCalibration','printerBorderless','printerDpi','printerAdd','printerDelete','printerSetDefault','pdfCreate','pdfSave','pdfShare','excelExport','csvExport','imageExport','bulkExport','exportOutsideApp','shareExternalApps','syncManual','syncAutomatic','syncWifiOnly','syncSettings','backupCreate','backupShare','backupRestore','backupEncrypted','backupDelete','backupOtherBranch','restoreOtherBranch','cloudSettings','googleShare','telegramBackup','whatsappBackup','logsViewOwn','logsViewAllBranches','logsSearch','logsFilter','logsExport','logsPrint','logsPdf','logsDeleteLocal','logsViewCritical','logsViewSecurity','logsViewDeviceActivity','notificationsView','notificationsMarkRead','notificationsDelete','notificationsDeleteCritical','notificationsViewBranches','notificationsManage','notificationsSecurity','notificationsMaintenance','notificationsBackup','notificationsDeviceAlerts','securityView','securityChangePassword','securityBiometric','securityPrivacyMode','securityAutoLock','securityOfflineAccess','securityOfflineDuration','securityForceReauth','securityDeviceSecrets','securitySessions','securityRevokeSessions','securityScreenshot','securityAudit','settingsView','settingsAppearance','settingsThemes','settingsFonts','settingsCardFonts','settingsPrinting','settingsSync','settingsArchive','settingsWhatsApp','settingsTelegram','settingsStorage','settingsPermissions','settingsReset','settingsFactoryReset','adminViewAllBranches','adminOpenBranchReport','adminTransferFiles','adminDisableBranch','adminDisableBranchSync','adminDisableBranchExport','adminDisableBranchPrint','adminDisableBranchDelete','adminForcePasswordChange','adminForceLogout','adminSetOfflineHours','adminLockDeviceNow','adminViewLastSync','adminViewStorageUsage','adminViewFileCount','adminOpenBranchFiles','adminFreezeReadOnly','adminSetViewOnly','adminSetPrintOnly','adminSetDesignOnly','adminSetDocumentsOnly','adminPermissionTemplates','adminBulkApplyPermissions']::text[]);
$$;

update public.abu_bassam_devices
set permissions=permissions - 'questionsView' - 'questionsCreate' - 'questionsEdit' - 'questionsDelete' - 'questionsTemplates' - 'questionsCustomTemplates' - 'questionsAnswersToggle' - 'questionsImages' - 'questionsPrint' - 'questionsPdf' - 'questionsReset' - 'questionsMaintenance' - 'compressUse' - 'compressBatch' - 'compressSave' - 'compressExport' - 'compressHighResolution' - 'compressDeleteOriginal' - 'printQuestions'
where permissions is not null;

revoke all on function public._abu_bassam_permission_key_allowed(text) from public,anon,authenticated;
